for n in names:
    var = Int(n.replace(" ", "_") + "_house")
    name_house[n] = var
    s.add(And(var >= 1, var <= 3))

mother_house = {}
for m in mothers:
    var = Int(m.replace(" ", "_") + "_house")
    mother_house[m] = var
    s.add(And(var >= 1, var <= 3))

lunch_house = {}
for l in lunches:
    var = Int(l.replace(" ", "_") + "_house")
    lunch_house[l] = var
    s.add(And(var >= 1, var <= 3))

s.add(Distinct([name_house[n] for n in names]))
s.add(Distinct([mother_house[m] for m in mothers]))
s.add(Distinct([lunch_house[l] for l in lunches]))

# 1. The spaghetti eater and Peter are next to each other.
s.add(Abs(lunch_house["spaghetti"] - name_house["Peter"]) == 1)

# 2. Grilled cheese is directly left of Aniya.
s.add(lunch_house["grilled cheese"] == mother_house["Aniya"] - 1)

# 3. The person who eats grilled cheese is Eric.
s.add(lunch_house["grilled cheese"] == name_house["Eric"])

# 4. Peter's mother is Holly.
s.add(name_house["Peter"] == mother_house["Holly"])

if s.check() == sat:
    model = s.model()

    name_at = {}
    mother_at = {}
    lunch_at = {}

    for n in names:
        h = model.eval(name_house[n], model_completion=True).as_long()
